DECLARE @n sysname, @i int = 0;
WHILE @i < 34
BEGIN
  SELECT @n = name FROM sys.syslanguages WHERE langid = @i;
  SET LANGUAGE @n;
  SELECT @@LANGUAGE AS lang, @@LANGID AS langid, @@DATEFIRST AS datefirst, DATENAME(month, '20240315') AS m, DATENAME(weekday, '20240315') AS wd;
  SET @i += 1;
END
